<?php require_once __DIR__.'/../includes/functions.php';$pdo=db();$publicServices=$pdo->query('SELECT * FROM services WHERE status="Active" AND public_booking_enabled=1 ORDER BY name')->fetchAll();$error='';$success=null;if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$patientId=trim((string)post('patient_id'));$first=trim((string)post('first_name'));$middle=trim((string)post('middle_name'));$last=trim((string)post('last_name'));$birth=(string)post('birth_date');$contact=trim((string)post('contact_number'));$barangay=(string)post('barangay');$sid=(int)post('service_id');$date=(string)post('appointment_date');$time=(string)post('appointment_time');$vaccine=trim((string)post('vaccine_type'));$purpose=trim((string)post('purpose'));if(!$first||!$last||!$birth||!$contact||!$barangay||!$sid||!$date||!$time)throw new Exception('Please complete all required fields.');$q=$pdo->prepare('SELECT * FROM services WHERE id=? AND status="Active" AND public_booking_enabled=1');$q->execute([$sid]);$svc=$q->fetch();if(!$svc)throw new Exception('That service is not available for public booking.');if($date<date('Y-m-d'))throw new Exception('Appointment date cannot be in the past.');$q=$pdo->prepare('SELECT COUNT(*) FROM appointments WHERE service_id=? AND appointment_date=? AND status IN ("Pending","Scheduled")');$q->execute([$sid,$date]);if((int)$q->fetchColumn()>=(int)$svc['daily_capacity'])throw new Exception('The selected service is full on that date. Please choose another date.');if($patientId){$q=$pdo->prepare('SELECT * FROM residents WHERE patient_id=? AND status="Active"');$q->execute([$patientId]);$resident=$q->fetch();if(!$resident)throw new Exception('Patient ID was not found. Leave Patient ID blank if you are registering for the first time.');$rid=(int)$resident['id'];}else{$pdo->beginTransaction();$pdo->prepare('INSERT INTO residents(patient_id,first_name,middle_name,last_name,birth_date,sex,contact_number,barangay,created_by) VALUES("PENDING",?,?,?,?,?,?,?,NULL)')->execute([$first,$middle,$last,$birth,'Other',$contact,$barangay]);$rid=(int)$pdo->lastInsertId();$pid='SR-'.date('Y').'-'.str_pad((string)$rid,6,'0',STR_PAD_LEFT);$pdo->prepare('UPDATE residents SET patient_id=? WHERE id=?')->execute([$pid,$rid]);$pdo->commit();$patientId=$pid;} $ref='APT-'.date('YmdHis').'-'.strtoupper(bin2hex(random_bytes(2)));$pdo->prepare('INSERT INTO appointments(reference_no,resident_id,service_id,appointment_date,appointment_time,purpose,vaccine_type,status) VALUES(?,?,?,?,?,?,?,"Pending")')->execute([$ref,$rid,$sid,$date,$time,$purpose,$vaccine]);audit('APPOINTMENT_CREATE','appointments',(int)$pdo->lastInsertId(),'Public appointment request '.$ref);$success=['ref'=>$ref,'patient_id'=>$patientId,'date'=>$date,'time'=>$time,'service'=>$svc['name']];}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Appointments | CHMS</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.css" rel="stylesheet"><link href="<?=BASE_URL?>/assets/css/public.css" rel="stylesheet"></head><body><?php include __DIR__.'/../includes/public_nav.php';?><main class="container py-5"><h1>Request an Appointment</h1><p class="text-muted">Public booking is limited to Dental, Family Planning and Immunization services enabled by the CHO.</p><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><?php if($success):?><div class="public-card border-success mb-4"><h3>Appointment request submitted</h3><p><b>Appointment Reference:</b> <?=e($success['ref'])?><br><b>Patient ID:</b> <?=e($success['patient_id'])?><br><b>Date:</b> <?=e($success['date'])?><br><b>Time:</b> <?=e($success['time'])?><br><b>Service:</b> <?=e($success['service'])?><br><b>Status:</b> Pending</p><p class="mb-0">Keep the reference number to check status. The CHO may confirm or reschedule the request.</p></div><?php endif;?><div class="panel public-card"><form method="post" class="row g-3"><?=csrf_field()?><div class="col-md-4"><label>Existing Patient ID</label><input name="patient_id" class="form-control" placeholder="SR-2026-000001"></div><div class="col-md-8"><div class="form-text mt-4">If you already have a Patient ID, enter it. Otherwise leave blank and the system will create one.</div></div><div class="col-md-4"><label>First Name *</label><input name="first_name" class="form-control" required></div><div class="col-md-4"><label>Middle Name</label><input name="middle_name" class="form-control"></div><div class="col-md-4"><label>Last Name *</label><input name="last_name" class="form-control" required></div><div class="col-md-3"><label>Birth Date *</label><input type="date" name="birth_date" class="form-control" required></div><div class="col-md-3"><label>Contact Number *</label><input name="contact_number" class="form-control" required></div><div class="col-md-3"><label>Barangay *</label><select name="barangay" class="form-select" required><option value="">Select</option><?php foreach(all_barangays() as $b):?><option><?=e($b)?></option><?php endforeach;?></select></div><div class="col-md-3"><label>Service *</label><select name="service_id" class="form-select" required><?php foreach($publicServices as $s):?><option value="<?=$s['id']?>"><?=e($s['name'])?></option><?php endforeach;?></select></div><div class="col-md-3"><label>Date *</label><input type="date" name="appointment_date" min="<?=date('Y-m-d')?>" class="form-control" required></div><div class="col-md-3"><label>Time *</label><input type="time" name="appointment_time" class="form-control" required></div><div class="col-md-6"><label>Vaccine Type (Immunization only)</label><select name="vaccine_type" class="form-select"><option value="">Not applicable</option><?php foreach(['BCG','Hepatitis B','Pentavalent','Polio','PCV','MMR','Influenza','COVID-19','Other'] as $v):?><option><?=$v?></option><?php endforeach;?></select></div><div class="col-12"><label>Purpose</label><textarea name="purpose" class="form-control" rows="3"></textarea></div><div class="col-12"><button class="btn btn-primary btn-lg">Submit Appointment Request</button></div></form></div></main></body></html>
